// 9대 핵심 전술 피처 표준화 상수 (NBA 2019-2026 전체 모집단 기준)
const FEATURE_MEANS = {
  three_point_share: 0.4246,
  ft_rate: 0.2412,
  pass_vs_shoot: 0.3059,
  ast_to_tov: 1.9086,
  orb_share: 0.2437,
  perimeter_def_ratio: 0.6173,
  stocks: 1.8928,
  fga_per_36_min: 11.6937,
  trb_per_36_min: 6.4324
};

const FEATURE_STDS = {
  three_point_share: 0.2135,
  ft_rate: 0.1378,
  pass_vs_shoot: 0.1781,
  ast_to_tov: 0.9253,
  orb_share: 0.1020,
  perimeter_def_ratio: 0.1815,
  stocks: 0.7559,
  fga_per_36_min: 3.3845,
  trb_per_36_min: 2.8500
};

/**
 * 💡 [KNN (K-Nearest Neighbors) 9차원 전술 거리 계산기]
 * 복잡한 코사인 유사도 대신, 9차원 표준화 공간에서 타겟 선수와의 '유클리디안 거리(Tactical Distance)'를 측정합니다.
 * 거리가 0에 가까울수록 쌍둥이처럼 플레이스타일이 일치하며, 거리가 멀어질수록 상극입니다.
 */
export function calculateKNNDistance(p1, p2) {
  if (!p1 || !p2) {
    return { distance: 9.99, tier: '측정 불가', score: 0 };
  }

  // 9차원 Z-score 차이의 제곱합(Squared Distance) 산출
  let sumSq = 0;
  const keys = Object.keys(FEATURE_MEANS);

  for (const k of keys) {
    const v1 = p1.features?.[k] ?? FEATURE_MEANS[k];
    const v2 = p2.features?.[k] ?? FEATURE_MEANS[k];
    const mean = FEATURE_MEANS[k];
    const std = FEATURE_STDS[k] || 1;

    const z1 = (v1 - mean) / std;
    const z2 = (v2 - mean) / std;
    const diff = z1 - z2;
    sumSq += diff * diff;
  }

  const distance = Math.sqrt(sumSq);

  // 이종 군집 페널티 (군집이 다르면 전술 적합도 추가 거리 반영)
  const isDifferentCluster = p1.clusterId !== p2.clusterId;
  const effectiveDistance = isDifferentCluster ? distance * 1.25 : distance;

  // 거리 기반 이웃 등급 판정
  let tier = '유사 롤 이웃';
  if (effectiveDistance < 1.2) {
    tier = '🥇 초근접 이웃 (쌍둥이형)';
  } else if (effectiveDistance < 2.0) {
    tier = '🥈 근접 이웃 (호환형)';
  } else if (effectiveDistance < 3.2) {
    tier = '🥉 유사 롤 이웃';
  } else {
    tier = '⚠️ 원거리 이웃 (비호환)';
  }

  // 직관적 100점 환산 적합도 (거리 0 = 99점, 거리 1.0 = 92점, 거리 2.0 = 80점, 거리 5+ = 20점대 바닥)
  let score = Math.round(100 - effectiveDistance * 11.5);
  score = Math.max(12, Math.min(99, score));

  return {
    distance: parseFloat(effectiveDistance.toFixed(2)),
    rawDistance: parseFloat(distance.toFixed(2)),
    tier,
    score
  };
}

/**
 * 하위 호환용 유사도 반환 함수 (KNN 거리 기반 실측 스코어 연동)
 */
export function calculateSimilarity(p1, p2) {
  const { score } = calculateKNNDistance(p1, p2);
  return score.toFixed(1);
}

